Translate("zhCN", "felwood", {
	title = "费伍德森林",
	sections = {
		{
			title = "概述",
			text = [=[费伍德森林是{link:kalimdor}卡利姆多{/link}北部一片垂死的森林，南接{link:ashenvale}灰谷{/link}，东北是{link:winterspring}冬泉谷{/link}的积雪。它的树木焦黑扭曲，溪水泛绿发臭，空气中弥漫着腐烂与烟熏的气味。它曾是{link:night-elves}暗夜精灵{/link}大森林的北部。如今它是{link:burning-legion}燃烧军团{/link}被逐出世界时留下的伤口。费伍德森林的野兽疯狂，{link:furbolgs}熊怪{/link}野蛮，恶魔仍在它的谷地中行走。然而仍有几位德鲁伊留在它南部的{link:moonglade}林地{/link}里，他们没有放弃这片森林。]=],
		},
		{
			title = "起源",
			text = [=[无数个世代以来，这片森林都是{link:night-elves}暗夜精灵{/link}的家园。他们的月亮井和兽穴散布其间，{link:ruins-of-constellas}克斯特拉斯废墟{/link}的白色石块至今仍矗立在西部的{link:moonglade}林地{/link}中。守护卡多雷的树人古树在林间安家。{link:third-war}第三次战争{/link}中，{link:burning-legion}燃烧军团{/link}来到了{link:kalimdor}卡利姆多{/link}。恐惧魔王{link:tichondrius}提克迪奥斯{/link}把{link:gul-dan}古尔丹{/link}之颅带进了森林，这件遗物充满了恶魔之力，他借着它向大地灌注腐化。地狱火燃烧着从天而降，留下至今仍在溃烂的陨坑。当{link:illidan-stormrage}伊利丹·怒风{/link}把颅骨的力量据为己有并杀死恐惧魔王时，损害早已造成。幸存下来的森林成了一片邪能之林，人们开始称它为费伍德森林。]=],
		},
		{
			title = "当今",
			text = [=[费伍德森林不属于任何人，许多势力在此争夺。在南方，{link:emerald-circle}翡翠议会{/link}的德鲁伊守着一座名为{link:emerald-sanctuary}翡翠圣地{/link}的小营地，在那里研究这场病害并寻找治愈之法。{link:horde}部落{/link}占据着西部的{link:bloodvenom-post}血毒岗哨{/link}，{link:alliance}联盟{/link}则在东北的{link:talonbranch-glade}刺枝林地{/link}设有一处角鹰兽栖所。两者之间是敌人。{link:shadow-council}暗影议会{/link}的术士把{link:jaedenar}加德纳尔{/link}作为他们组织的总部，在那里与恶魔交易。碧火{link:satyrs}萨特{/link}玷污了古老的月亮井。{link:deadwood-furbolgs}死木{/link}{link:furbolgs}熊怪{/link}已经发疯。在遥远的北方，{link:timbermaw-furbolgs}木喉熊怪{/link}把守着通往{link:winterspring}冬泉谷{/link}的通道，几乎谁也不信任。腐化并未停留在费伍德森林之内：{link:darkshore}黑海岸{/link}的德鲁伊担心它正向西渗入他们自己的森林。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:emerald-circle}翡翠议会{/link}。{/b} {link:cenarion-circle}塞纳里奥议会{/link}的德鲁伊，来自{link:alliance}联盟{/link}和{link:horde}部落{/link}双方，他们发誓要治愈这片森林。
• {b}{link:shadow-council}暗影议会{/link}。{/b} 占据{link:jaedenar}加德纳尔{/link}的术士和邪教徒，{link:burning-legion}燃烧军团{/link}的恶魔与他们并肩。
• {b}碧火{link:satyrs}萨特{/link}。{/b} 他们出没于{link:ruins-of-constellas}克斯特拉斯废墟{/link}、{link:jadefire-glen}碧火谷{/link}和{link:jadefire-run}碧火小径{/link}，所到之处散播腐化。
• {b}{link:deadwood-furbolgs}死木熊怪{/link}。{/b} 一个被邪能逼疯的部族，村落分布在森林的极南和极北。
• {b}{link:timbermaw-furbolgs}木喉熊怪{/link}。{/b} 唯一保持神智的部族，守卫着{link:timbermaw-hold}木喉要塞{/link}的隧道。
• {b}腐化的荒野。{/b} 扭木{link:elements}元素{/link}、枯萎的树人、软泥怪、发狂的熊、狼和枭兽，以及仍在{link:shatter-scar-vale}碎痕谷{/link}中行走的地狱火。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:night-elves}卡多雷{/link}的森林。{/b} 数千年来，北方的树林是一片宁静的土地，遍布月亮井、兽穴和古树。
• {b}{link:third-war}第三次战争{/link}。{/b} {link:burning-legion}燃烧军团{/link}的大军向{link:mount-hyjal}海加尔山{/link}进军。{link:tichondrius}提克迪奥斯{/link}用{link:skull-of-gul-dan}古尔丹之颅{/link}腐化了森林，地狱火被召唤降落其上。
• {b}{link:illidan-stormrage}伊利丹{/link}的抉择。{/b} 伊利丹·怒风吞噬了颅骨的力量，化为恶魔之形，在这片树林中杀死了提克迪奥斯。他的哥哥因此将他放逐。
• {b}当今。{/b} 燃烧军团的大军在{link:battle-of-mount-hyjal}海加尔山之战{/link}中被击溃，但费伍德森林并未痊愈。恶魔、{link:satyrs}萨特{/link}和术士仍在，只有寥寥几位德鲁伊与之对抗。]=],
		},
		{
			title = "森林传说",
			text = [=[• {link:emerald-circle}翡翠议会{/link}的德鲁伊学会了制作一种药膏，能使腐化的植物恢复健康。在他们的照料下，那些被认为已经绝迹的歌唱之花、风之花、鞭根和夜龙之花又重新开放了。
• 人们在一个{link:satyrs}萨特{/link}手中发现了一支用倒下的古树之木雕成的长笛。古树的灵魂被束缚在其中，无法安息，直到{link:temple-of-the-moon}月神殿{/link}的圣水使它获得自由。
• {link:shadow-council}暗影议会{/link}用四座火盆守卫它的堡垒，它们的名字是痛苦、恶意、苦难和仇恨。
• 三位{link:vartrus-the-ancient}古树瓦特鲁斯{/link}、斯托玛和哈斯塔特的灵魂，仍会回应那些来到{link:irontree-woods}铁木森林{/link}中某块岩石前的人。]=],
		},
	},
})

Translate("zhCN", "emerald-sanctuary", {
