	sections = {
		{
			title = "概述",
			text = [=[翡翠圣地是{link:felwood}费伍德森林{/link}南部的一座德鲁伊小营地，靠近{link:ashenvale}灰谷{/link}的边界。它是{link:emerald-circle}翡翠议会{/link}的家园。在这里，{link:night-elves}暗夜精灵{/link}和{link:tauren}牛头人{/link}的德鲁伊并肩工作，无论他们的族人在别处有何争端。他们收集森林中出产的每一种被污染之物的样本，寻求净化它的方法。双方的朋友在那里都受到欢迎。营地周围的森林黑暗而充满敌意，碧火{link:satyrs}萨特{/link}潜伏在附近的{link:stranglethorn-vale}山谷{/link}中。]=],
		},
	},
})

Translate("zhCN", "bloodvenom-post", {
	title = "血毒岗哨",
	sections = {
		{
			title = "概述",
			text = [=[血毒岗哨是{link:horde}部落{/link}在{link:felwood}费伍德森林{/link}西部的立足点，一座位于腐化树林边缘、由帐篷和栅栏组成的营地。来自{link:orgrimmar}奥格瑞玛{/link}的{link:orcs}兽人{/link}与来自{link:undercity}幽暗城{/link}的{link:forsaken}被遗忘者{/link}共享它的篝火。在这片充满敌意的土地上，这是一个艰苦的{link:morgan-s-vigil}岗哨{/link}。它的战士与{link:shadow-council}暗影议会{/link}和森林中发狂的{link:furbolgs}熊怪{/link}交过手，有些人再也没有回来。它的特工把目光投向更远的地方：一人研究{link:satyrs}萨特{/link}腐化的月亮井，另一人研究{link:winterspring}冬泉谷{/link}的枭兽。一位双足飞龙管理员使岗哨与部落的其他地方保持联系。]=],
		},
	},
})

Translate("zhCN", "talonbranch-glade", {
	title = "刺枝林地",
