			title = "概述",
			text = [=[刺枝林地是{link:felwood}费伍德森林{/link}东北部一座小小的{link:night-elves}暗夜精灵{/link}营地。角鹰兽栖息在它的树上，把信件和旅人送往{link:alliance}联盟{/link}的其他地方。几名卡多雷守着这里：一位商人、一位武器匠，以及为与腐化的长期战争训练德鲁伊和猎人的导师。这里是北上之前休息的地方，也是暗夜精灵在这片曾完全属于他们的森林中最后的前哨之一。]=],
		},
	},
})

Translate("zhCN", "jaedenar", {
