Translate("zhCN", "irontree-woods", {
	title = "铁木森林",
	aliases = { "铁木山洞" },
	sections = {
		{
			title = "概述",
			text = [=[铁木森林是{link:felwood}费伍德森林{/link}北部的腹地，一片枯萎的树木与废墟。树人曾作为森林的守护者在这里行走。腐化扭曲了它们，剩下的那些在枯树间游荡、践踏。在铁木山洞中，扭木{link:elements}元素{/link}已经堕落得太深，德鲁伊不再指望净化它们。然而这片树林并未完全失去。在它南部的废墟中，一位名叫阿{link:farmer-ray}雷{/link}的古树之灵仍在徘徊，另外三位古树的灵魂仍会在林间的一块石头前作出回应。]=],
		},
	},
})

Translate("zhCN", "shatter-scar-vale", {
	title = "碎痕谷",
	sections = {
		{
			title = "概述",
			text = [=[碎痕谷位于{link:felwood}费伍德森林{/link}中部大路以东。{link:third-war}第三次战争{/link}中，{link:burning-legion}燃烧军团{/link}把它的地狱火召唤到这座{link:stranglethorn-vale}山谷{/link}，它们砸出的陨坑至今仍在地面上留下伤疤。污浊的绿水积聚在坑中，从未澄清。地狱火仍在其间行走，没有头脑，只知破坏，身旁伴随着纯粹熵能构成的{link:elements}元素{/link}。德鲁伊曾希望在费伍德森林找到一处洁净的泉水。他们没有在这里找到。山谷中的某处躺着地狱火{link:kroshius}克罗苏斯{/link}燃尽的残骸。]=],
		},
	},
})

Translate("zhCN", "ruins-of-constellas", {
	title = "克斯特拉斯废墟",
