	sections = {
		{
			title = "概述",
			text = [=[碧火小径位于{link:felwood}费伍德森林{/link}西北部。它是碧火{link:satyrs}萨特{/link}的第二座营地，也是更危险的一座。地狱召唤者、{link:illidan-stormrage}背叛者{/link}和诡术师在萨特{link:xavaric}萨瓦里克{/link}麾下聚集于此，他收取了{link:ruins-of-constellas}克斯特拉斯{/link}那座腐化月亮井的成果。小径的萨特以森林生灵的腐化为食。人们在他们之中发现了一支用倒下的古树雕成的木笛，它让德鲁伊明白，萨特的残忍甚至触及了森林的守护者。]=],
		},
	},
})

Translate("zhCN", "deadwood-village", {
