			title = "概述",
			text = [=[木喉要塞是{link:timbermaw-furbolgs}木喉熊怪{/link}的家园，是{link:felwood}费伍德森林{/link}北缘群山中的一片隧道网络。它的通道穿过岩石通往{link:winterspring}冬泉谷{/link}，是北上的唯一道路。{link:furbolgs}熊怪{/link}们凶猛地守卫着这些通道。未赢得他们信任的陌生人会遭到长矛相迎，而杀死一个木喉熊怪，哪怕是出于自卫，也会被视为他们的敌人。在要塞内部，他们的长老、秘法师和商人维持着部族的生活，并研究那吞噬了他们同族的腐化。]=],
		},
	},
})

Translate("zhCN", "eridan-bluewind", {
