	sections = {
		{
			title = "概述",
			text = [=[提克迪奥斯是一位恐惧魔王，是侍奉{link:burning-legion}燃烧军团{/link}的纳斯{link:farmer-ray}雷{/link}兹姆之一。{link:third-war}第三次战争{/link}中，他是以燃烧军团之名指引{link:scourge}天灾军团{/link}的恶魔之一，他向死亡骑士{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}下达命令。燃烧军团来到{link:kalimdor}卡利姆多{/link}时，他把{link:gul-dan}古尔丹{/link}之颅带进北方的森林，用颅骨的黑暗力量毒害了它。那片森林就是{link:felwood}费伍德森林{/link}。他在那里被{link:illidan-stormrage}伊利丹·怒风{/link}所杀。]=],
		},
		{
			title = "意义",
			text = [=[在{link:third-war}第三次战争{/link}的所有恶魔中，提克迪奥斯在大地本身留下了最深的印记。{link:archimonde}阿克蒙德{/link}倒在{link:mount-hyjal}海加尔山{/link}，他的大军被击溃，但提克迪奥斯播下的腐化并没有随他而死。{link:felwood}费伍德森林{/link}中每一个发狂的{link:furbolgs}熊怪{/link}、每一棵枯萎的树人、每一座污浊的月亮井，都是他留下的遗产。他的死也永远地改变了{link:illidan-stormrage}伊利丹{/link}：为了打败他，伊利丹把颅骨的力量纳入自身，他的族人因此将他放逐。]=],
		},
		{
			title = "天灾军团与燃烧军团",
			text = [=[巫妖王创造了{link:scourge}天灾军团{/link}，却没有让它获得自由。{link:burning-legion}燃烧军团{/link}的恐惧魔王监视着它，提克迪奥斯就是其中之一。{link:arthas-menethil}阿尔萨斯{/link}杀死父亲、把自己完全交给天灾军团之后，提克迪奥斯考验了这位王子的忠诚，并给他分派任务。阿尔萨斯把死灵法师{link:kel-thuzad}克尔苏加德{/link}的遗骸带到{link:quel-thalas}奎尔萨拉斯{/link}的太阳之井，克尔苏加德在那里复活为巫妖。克尔苏加德又在{link:dalaran}达拉然{/link}把{link:archimonde}阿克蒙德{/link}召唤到这个世界。燃烧军团的主宰终于到来，天灾军团已完成了它的使命，恶魔们便转向了{link:kalimdor}卡利姆多{/link}。]=],
		},
		{
			title = "森林的毒化",
			text = [=[{link:archimonde}阿克蒙德{/link}的大军向{link:mount-hyjal}海加尔山{/link}和世界之树{link:nordrassil}诺达希尔{/link}进军。提克迪奥斯带着{link:skull-of-gul-dan}古尔丹之颅{/link}来到北方的森林，那是最早使{link:orcs}兽人{/link}与{link:burning-legion}燃烧军团{/link}结盟的术士的遗骸。颅骨中仍保留着{link:gul-dan}古尔丹{/link}的大量邪能，提克迪奥斯用它腐化了周围的树林。树木变黑，水质变坏。野兽和{link:furbolgs}熊怪{/link}发了疯。地狱火燃烧着从天而降，守护森林的古树被摧毁了。]=],
		},
		{
			title = "恐惧魔王之死",
			text = [=[{link:tyrande-whisperwind}泰兰德·语风{/link}把{link:illidan-stormrage}伊利丹{/link}从漫长的囚禁中释放出来，让他与恶魔作战。伊利丹得知了颅骨的存在，便去追寻它。他夺得了颅骨，吞噬了它的力量。这改变了他：他长出了角和巨大的黑色双翼，自己也变成了半个恶魔。凭借这股力量，他杀死了提克迪奥斯。这场胜利让他失去了其余的一切。{link:malfurion-stormrage}玛法里奥·怒风{/link}无法原谅他的弟弟变成的模样，将伊利丹逐出了{link:night-elves}暗夜精灵{/link}的森林。]=],
		},
		{
			title = "未载",
			text = [=[没有编年史讲述提克迪奥斯是如何得到颅骨的，也没有讲述他在{link:illidan-stormrage}伊利丹{/link}找到他之前在森林中待了多久。]=],
		},
	},
	chapters = {
		{
			title = "古树的记忆",
			hint = "引领一位古树之灵走出腐化的森林。",
			text = [=[古树之灵阿{link:farmer-ray}雷{/link}仍记得{link:burning-legion}燃烧军团{/link}到来之前的森林。她记得地狱火、毁灭与混乱。她记得{link:skull-of-gul-dan}古尔丹之颅{/link}确保了森林中没有任何东西幸免。即使身为灵魂，她也无法逃脱这片土地的苦难。她只请求被领出这里，好让她得以安息。]=],
