Translate("zhCN", "skull-of-gul-dan", {
	title = "古尔丹之颅",
	sections = {
		{
			title = "概述",
			text = [=[古尔丹之颅是{link:orcs}兽人{/link}术士、{link:shadow-council}暗影议会{/link}创始人{link:gul-dan}古尔丹{/link}的颅骨。它在术士死于{link:sargeras}萨格拉斯{/link}之墓后留存下来，并保留了他的大量邪能。{link:third-war}第三次战争{/link}中，恐惧魔王{link:tichondrius}提克迪奥斯{/link}把它带到{link:kalimdor}卡利姆多{/link}，用它腐化了北方的森林。{link:illidan-stormrage}伊利丹·怒风{/link}从他手中夺走了它，吞噬了它的力量，并因此变成了半恶魔的生物。]=],
		},
