			title = "遗患",
			text = [=[颅骨已不复存在，但它造成的影响依然存在。被它毒害的森林被称为{link:felwood}费伍德森林{/link}。古树之灵记得它没有放过任何东西，{link:emerald-circle}翡翠议会{/link}的德鲁伊至今仍在与它留下的一切抗争。]=],
		},
	},
})

Translate("zhCN", "shadow-council", {
	title = "暗影议会",
	aliases = { "议会" },
	sections = {
		{
			title = "概述",
			text = [=[暗影议会是一个侍奉{link:burning-legion}燃烧军团{/link}的秘密术士组织。它诞生于德拉诺的{link:orcs}兽人{/link}之中，比它曾统治过的{link:horde}部落{/link}存续得更久。如今它的总部设在{link:felwood}费伍德森林{/link}的{link:jaedenar}加德纳尔{/link}，它的分支散布在世界各地。]=],
		},
		{
			title = "起源",
			text = [=[恶魔领主{link:kil-jaeden}基尔加丹{/link}选中术士{link:gul-dan}古尔丹{/link}作为他在{link:orcs}兽人{/link}中的仆从。古尔丹把他的术士同伴中最有野心的人聚集成一个隐秘的议会。它通过一位傀儡酋长在幕后统治兽人各氏族，并引导他们饮下了{link:mannoroth}玛诺洛斯{/link}之血。它通过古尔丹打开了{link:dark-portal}黑暗之门{/link}。]=],
		},
		{
			title = "覆灭",
			text = [=[{link:first-war}第一次战争{/link}之后的日子里，暗影议会把总部设在{red:blackrock-spire}黑石塔{/red}。{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}在那里向它发难，杀死了它的大部分成员，并俘虏了{link:gul-dan}古尔丹{/link}。古尔丹后来背叛了{link:horde}部落{/link}并死去。人们以为暗影议会已随他而亡。]=],
		},
		{
			title = "当今",
			text = [=[它并没有消亡。在{link:jaedenar}加德纳尔{/link}，{link:shadow-lord-fel-dan}暗影领主费尔丹{/link}领导着这个组织并与{link:burning-legion}燃烧军团{/link}缔结契约，而一位恐惧魔王在下方的深处坐镇。{link:felwood}费伍德森林{/link}内外的许多罪恶都被归咎于暗影议会。它的印记出现在{link:arathi-highlands}阿拉希高地{/link}的术士之中。在{link:orgrimmar}奥格瑞玛{/link}，{link:burning-blade}火刃氏族{/link}和灼热之刃为它的目的效力，{link:blasted-lands}诅咒之地{/link}的暗誓者是它的继承者。{link:thrall}萨尔{/link}知道它还活着，他决心找到它。]=],
		},
	},
})

Translate("zhCN", "emerald-circle", {
	title = "翡翠议会",
	sections = {
		{
			title = "概述",
			text = [=[翡翠议会是{link:cenarion-circle}塞纳里奥议会{/link}中致力于{link:felwood}费伍德森林{/link}的德鲁伊团体。{link:night-elves}暗夜精灵{/link}和{link:tauren}牛头人{/link}在其中一同效力，他们同样欢迎{link:alliance}联盟{/link}和{link:horde}部落{/link}的朋友。他们以{link:emerald-sanctuary}翡翠圣地{/link}为基地，研究腐化并设法逆转它。]=],
		},
		{
			title = "他们的工作",
			text = [=[• 他们与散播和助长腐化的碧火{link:satyrs}萨特{/link}以及{link:shadow-council}暗影议会{/link}作战。
• 他们学会了制作治愈腐化植物的药膏，但只把这门知识传给证明了自己的人。
• 他们寻找洁净的水源，以及也许能治愈森林树木与生灵的解药。
• 他们研究{link:felwood}费伍德森林{/link}内外的{link:furbolgs}熊怪{/link}，以及吞噬了它们的疯狂。]=],
		},
		{ title = "未载", text = "没有编年史记载翡翠议会是何时建立的，也没有记载最初由谁领导。" },
	},
})

Translate("zhCN", "deadwood-furbolgs", {
