	sections = {
		{
			title = "概述",
			text = [=[死木是{link:felwood}费伍德森林{/link}中被邪能逼疯的一个{link:furbolgs}熊怪{/link}部族。他们占据着森林南部的{link:deadwood-village}死木村{/link}和北部的{link:felpaw-village}魔爪村{/link}，攻击一切靠近的人。]=],
		},
		{
			title = "疯狂",
			text = [=[{link:timbermaw-furbolgs}木喉熊怪{/link}说，死木熊怪生性并不邪恶。是邪能污染了他们的心智，而且无法挽回。他们的仪式图腾散发着腐朽与绝望的气息。在他们北方的营地里，一口大锅中冒着泡的是一种绿色的腐臭酿液，它也许正把疯狂传播给{link:winterspring}冬泉谷{/link}的{link:winterfall-furbolgs}寒水熊怪{/link}。]=],
		},
		{
			title = "首领",
			text = [=[• {b}{link:overlord-ror}主宰洛尔{/link}{/b} 统治着南方的{link:deadwood-village}死木村{/link}。
• {b}酋长血喉{/b} 统治着北方{link:timbermaw-hold}木喉要塞{/link}附近的营地。]=],
