	},
})

Translate("zhCN", "timbermaw-furbolgs", {
	title = "木喉熊怪",
	aliases = { "木喉", "木喉部族" },
	sections = {
		{
			title = "概述",
			text = [=[木喉是唯一逃过腐化的{link:furbolgs}熊怪{/link}部族。他们居住在{link:timbermaw-hold}木喉要塞{/link}，即{link:felwood}费伍德森林{/link}与{link:winterspring}冬泉谷{/link}之间的隧道中，并守卫着它们，抵御一切来犯者。]=],
		},
		{
			title = "谨慎的族群",
			text = [=[木喉熊怪信任的人极少。如今许多旅人见到{link:furbolgs}熊怪{/link}就杀，从不问它是敌是友。木喉熊怪从中吸取了教训。他们只欢迎那些在对抗腐化部族——{link:felwood}费伍德森林{/link}的{link:deadwood-furbolgs}死木熊怪{/link}和{link:winterspring}冬泉谷{/link}的{link:winterfall-furbolgs}寒水熊怪{/link}——中证明了自己的人。与同族作战令他们悲伤，但他们还是这样做了。{link:ironforge}铁炉堡{/link}的{link:magni-bronzebeard}麦格尼{/link}国王和{link:horde}部落{/link}的大酋长过去都曾尝试与他们接触。]=],
		},
		{
			title = "他们的希望",
			text = [=[木喉熊怪相信{link:winterfall-furbolgs}寒水熊怪{/link}受一个恶魔统治。如果它被消灭，寒水熊怪的治愈就能开始，要塞也将在未来许多年里安然无恙。]=],
		},
	},
})

